use crate::list::persistent::tests::wallet;
use super::*;
#[test]
fn original_persistent_builder_close_preserves_real_child_work_and_empty_scan_custody(){
 let row:serde_json::Value=serde_json::from_str::<serde_json::Value>(include_str!("../../🎟️work/📐️.json")).unwrap()["closeLaw"].clone();let s=&row["stock"];let mut bank=RetainedCloneGrant{maximum_items:s["items"].as_u64().unwrap()as usize,maximum_copy_bytes:s["copyBytes"].as_u64().unwrap()as usize,maximum_capacity_bytes:s["capacityBytes"].as_u64().unwrap()as usize,maximum_release_bytes:s["releaseBytes"].as_u64().unwrap()as usize,maximum_depth:s["depth"].as_u64().unwrap()as usize};let mut fuel=s["fuel"].as_u64().unwrap();let mut owner=PersistentListBuilder::<u64>::new(1);let value=row["value"].as_u64().unwrap();let turn=crate::admit_funded(value,crate::shared_issuance::SharedIssuer::owned(),RetainedCloneGrant{maximum_items:1,..bank});fuel=fuel.checked_sub(u64::try_from(turn.work).unwrap()).unwrap();let(shared,p)=turn.result.map_err(|(error,_)|error).unwrap();bank.maximum_items-=p.copied_items;bank.maximum_copy_bytes-=p.copied_bytes;bank.maximum_capacity_bytes-=p.retained_capacity_bytes;assert_eq!(serde_json::to_value(*shared.get()).unwrap(),row["value"]);let mut shared=Some(shared);let turn=wallet::run(RetainedCloneGrant{maximum_items:1,..bank},|effect,reply|owner.adopt_into(&mut shared,effect,reply));fuel=fuel.checked_sub(u64::try_from(turn.work).unwrap()).unwrap();let p=turn.result.unwrap().progress();bank.maximum_items-=p.copied_items;bank.maximum_copy_bytes-=p.copied_bytes;{let turn=wallet::begin(RetainedCloneGrant{maximum_items:1,..bank},|effect|owner.begin_close_paid(effect));fuel=fuel.checked_sub(u64::try_from(turn.work).unwrap()).unwrap();let p=turn.result.unwrap().progress();bank.maximum_items-=p.copied_items;bank.maximum_copy_bytes-=p.copied_bytes;}let pointer=owner.rows[0].as_ref().unwrap().identity();let denied=crate::effect::settle(Default::default(),|effect|wallet::poll(effect,|effect,reply|owner.close_into(effect.grant().maximum_copy_bytes,effect,reply)));assert_eq!(denied.work,u128::from(row["deniedWork"].as_u64().unwrap()));assert_eq!(owner.rows[0].as_ref().unwrap().identity(),pointer);
 for _ in 0..s["maximumTurns"].as_u64().unwrap(){if owner.terminal_is_empty(){break}let selected=owner.close_work_demand(bank.maximum_copy_bytes).unwrap();let(turn,heap)=semio_framework_value_testing_allocator::observe_retirement_allocations(||crate::effect::settle(RetainedCloneGrant{maximum_items:1,..bank},|effect|wallet::poll(effect,|effect,reply|owner.close_into(effect.grant().maximum_copy_bytes,effect,reply))));assert!(turn.work<=u128::from(selected));fuel=fuel.checked_sub(u64::try_from(turn.work).unwrap()).unwrap();let p=turn.result.unwrap().progress();assert!(p.fits(bank));assert_eq!((p.retained_capacity_bytes,p.released_bytes),heap);bank.maximum_items-=p.copied_items;bank.maximum_copy_bytes-=p.copied_bytes;bank.maximum_capacity_bytes-=p.retained_capacity_bytes;bank.maximum_release_bytes-=p.released_bytes;}
 assert!(owner.terminal_is_empty());let cached=crate::effect::settle(Default::default(),|effect|wallet::poll(effect,|effect,reply|owner.close_into(effect.grant().maximum_copy_bytes,effect,reply)));assert_eq!(cached.work,u128::from(row["cachedWork"].as_u64().unwrap()));assert_eq!(cached.result.unwrap().progress(),Default::default());
}
